import java.util.*;

public class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        // If endWord is not in wordList, no valid transformation
        if (!wordList.contains(endWord)) return 0;

        int L = beginWord.length();
        // Preprocess: build a map of intermediate forms to the list of words
        Map<String, List<String>> allComboDict = new HashMap<>();
        // Ensure beginWord included so its generic forms are present
        List<String> extended = new ArrayList<>(wordList);
        if (!extended.contains(beginWord)) extended.add(beginWord);

        for (String word : extended) {
            for (int i = 0; i < L; i++) {
                String key = word.substring(0, i) + '*' + word.substring(i + 1);
                allComboDict.computeIfAbsent(key, k -> new ArrayList<>()).add(word);
            }
        }

        // BFS
        Queue<Pair> queue = new LinkedList<>();
        queue.add(new Pair(beginWord, 1));
        Set<String> visited = new HashSet<>();
        visited.add(beginWord);

        while (!queue.isEmpty()) {
            Pair node = queue.poll();
            String word = node.word;
            int level = node.level;

            for (int i = 0; i < L; i++) {
                String intermediate = word.substring(0, i) + '*' + word.substring(i + 1);

                List<String> adjacent = allComboDict.getOrDefault(intermediate, Collections.emptyList());
                for (String adjacentWord : adjacent) {
                    if (adjacentWord.equals(endWord)) {
                        return level + 1;
                    }
                    if (!visited.contains(adjacentWord)) {
                        visited.add(adjacentWord);
                        queue.add(new Pair(adjacentWord, level + 1));
                    }
                }
                // Optional optimization: clear list to prevent redundant processing
                allComboDict.put(intermediate, Collections.emptyList());
            }
        }
        return 0;
    }

    private static class Pair {
        String word;
        int level;
        Pair(String w, int l) { word = w; level = l; }
    }
}

